const statusOf = (error: any) => Number(error?.$metadata?.httpStatusCode ?? error?.statusCode ?? 0);

/** HEADs one preview object (optionally an exact version); a missing object is null, not an error. */
export const headMotionPreviewObject = async (
    s3Key: string,
    versionId?: string | null
): Promise<MotionPreviewHeadResult | null> => {
    try {
        return await getS3().send(new HeadObjectCommand({
            Bucket: process.env.S3_BUCKET_NAME!,
            Key: s3Key,
            VersionId: versionId ?? undefined
        }));
    } catch (error: any) {
        if (statusOf(error) === 404 || error?.name === 'NotFound') return null;
        throw error;
    }
};

const defaultDependencies: MotionPreviewLifecycleDependencies = {
    findTrack: (mediaTrackId) => AudioTrack.findById(mediaTrackId),
    updateTrackWhere: updateMediaTrackStorageState,
    putObject: async (s3Key, file, metadata, signal) => {
        const body = file.path ? createReadStream(file.path) : file.buffer;
        const result = await getS3().send(new PutObjectCommand({
            Bucket: process.env.S3_BUCKET_NAME!,
            Key: s3Key,
            Body: body,
            // A retried PUT must never create a second version under the same never-reused key.
            IfNoneMatch: '*',
            ContentLength: file.size,
            ContentType: 'video/mp4',
            Metadata: metadata
        }), { abortSignal: signal });
        return { ETag: result.ETag, VersionId: result.VersionId };
    },
    headObject: headMotionPreviewObject,
    deleteObject: async (s3Key, versionId) => {
        await getS3().send(new DeleteObjectCommand({
            Bucket: process.env.S3_BUCKET_NAME!,
            Key: s3Key,
            // A bucket without versioning reports no version; S3 addresses that object exactly as 'null'.
            VersionId: versionId ?? 'null'
        }));
    },
    createObjectKey: createMotionPreviewObjectKey,
    validate: (file, signal) => validateMotionPreviewFile(file, signal),
    now: () => new Date(),
    randomRevision: () => `pv_${randomBytes(16).toString('hex')}`
};

const errorText = (error: unknown) => String((error as Error)?.message ?? error).slice(0, 500);

/** The opaque binding a client echoes so an upload targets the Video it was made for. */
export const motionPreviewSourceToken = (mediaTrackId: string, sourceKey: string) => (
    createHash('sha256').update(`${mediaTrackId}:${sourceKey}`).digest('hex').slice(0, 32)
);

/** Only an explicit, ready Video MediaTrack can hold a preview; legacy rows migrate on replacement first. */
const previewSourceFor = (track: any, mediaTrackId: string) => {
    if (!track || track.uploadStatus !== 'ready' || track.mediaType !== 'video'
        || activeMediaTypeForTrack(track) !== 'video') return null;
    const sourceKey = activeMediaObjectKeyForTrack(track);
    return sourceKey && sourceKey === track.s3Key ? { sourceKey, mediaTrackId } : null;
};

const stateOf = (track: any): MotionPreviewState | null => track?.motionPreview ?? null;

/**
 * Once MediaTrack deletion begins it owns every preview object, so no preview write may change the
 * record its fence compares.
 */
const notDeleting = { uploadStatus: { $nin: ['deleting', 'deleteFailed'] } };

/** Whether MediaTrack deletion owns this track's preview objects, so preview work must not touch them. */
const deletionOwns = (track: any) => track?.uploadStatus === 'deleting' || track?.uploadStatus === 'deleteFailed';

/**
 * Identifies the exact object a pending upload may have written. A recorded outcome is used as is;
 * an unknown one is resolved by HEAD on the never-reused key, whose metadata must name the
 * MediaTrack. Returns null when no object exists and throws when the object cannot be identified
 * exactly. A missing VersionId is S3's exact null version in a bucket without versioning.
 */
export const resolvePendingMotionPreviewObject = async (
    pending: NonNullable<MotionPreviewState['pending']>,
    mediaTrackId: string,
    headObject: (s3Key: string) => Promise<MotionPreviewHeadResult | null>
): Promise<{ key: string; versionId: string | null } | null> => {
    if (!isMotionPreviewObjectKeyForTrack(pending.s3Key, mediaTrackId)) {
        throw new Error('The pending preview key is missing or invalid.');
    }
    if (!pending.outcomeUnknown) return { key: pending.s3Key, versionId: pending.versionId ?? null };
    const head = await headObject(pending.s3Key);
    if (!head) return null;
    // Object metadata records the lowercase id; callers may pass any hex case.
    if (head.Metadata?.trackid !== String(mediaTrackId ?? '').trim().toLowerCase()) {
        throw new Error('The pending preview object cannot be identified exactly.');
    }
    return { key: pending.s3Key, versionId: head.VersionId ?? null };
};

/** Creates the empty lifecycle record once, so every later write is a compare-and-set on its revision. */
const ensureState = async (mediaTrackId: string, deps: MotionPreviewLifecycleDependencies) => {
    let track = await deps.findTrack(mediaTrackId);
    if (!track) throw new MotionPreviewLifecycleError(404, 'ADMIN_MOTION_PREVIEW_NOT_FOUND');
    if (stateOf(track)) return track;
    await deps.updateTrackWhere(mediaTrackId, { ...notDeleting, motionPreview: null }, {
        motionPreview: { active: null, pending: null, cleanup: null, revision: 0 }
    });
    track = await deps.findTrack(mediaTrackId);
    if (!stateOf(track)) throw conflict('ADMIN_MOTION_PREVIEW_STALE_REVISION');
    return track;
};

/** Deletes a detached cleanup object by exact version, then clears or marks the slot. */
const drainCleanup = async (mediaTrackId: string, deps: MotionPreviewLifecycleDependencies) => {
    const track = await deps.findTrack(mediaTrackId);
    const state = stateOf(track);
    const cleanup = state?.cleanup;
    if (!state || !cleanup) return { cleanupPending: false };
    if (deletionOwns(track)) return { cleanupPending: true };
    if (!isMotionPreviewObjectKeyForTrack(cleanup.s3Key, mediaTrackId)) return { cleanupPending: true };
    try {
        await deps.deleteObject(cleanup.s3Key, cleanup.versionId);
    } catch (error) {
        await deps.updateTrackWhere(mediaTrackId, {
            ...notDeleting,
            'motionPreview.revision': state.revision,
            'motionPreview.cleanup.s3Key': cleanup.s3Key
        }, {
            'motionPreview.cleanup.status': 'deleteFailed',
            'motionPreview.cleanup.updatedAt': deps.now(),
            'motionPreview.cleanup.error': errorText(error),
            'motionPreview.revision': state.revision + 1
        }).catch(() => undefined);
        return { cleanupPending: true };
    }
    const cleared = await deps.updateTrackWhere(mediaTrackId, {
        ...notDeleting,
        'motionPreview.revision': state.revision,
        'motionPreview.cleanup.s3Key': cleanup.s3Key
    }, { 'motionPreview.cleanup': null, 'motionPreview.revision': state.revision + 1 });
    return { cleanupPending: cleared.matchedCount !== 1 };
};

/**
 * Resolves a pending upload that is no longer protected by its lease. The record is fenced first,
 * so a late write from that upload can no longer record or promote what this step deletes; then the
 * exact object (a recorded version, or the version HEAD identifies on the never-reused key) is
 * deleted. Nothing is ever deleted by key alone.
 */
const drainPending = async (mediaTrackId: string, deps: MotionPreviewLifecycleDependencies) => {
    const track = await deps.findTrack(mediaTrackId);
    const state = stateOf(track);
    const pending = state?.pending;
    if (!state || !pending) return;
    if (deletionOwns(track)) throw conflict('ADMIN_MOTION_PREVIEW_BUSY');
    if (pending.status === 'uploading' && new Date(pending.leaseUntil).getTime() > deps.now().getTime()) {
        throw conflict('ADMIN_MOTION_PREVIEW_BUSY');
    }
    const reconciliationRequired = () => new MotionPreviewLifecycleError(503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    let target: { key: string; versionId: string | null } | null;
    try {
        target = await resolvePendingMotionPreviewObject(pending, mediaTrackId, (key) => deps.headObject(key));
    } catch {
        throw reconciliationRequired();
    }
    const fenced = await deps.updateTrackWhere(mediaTrackId, {
        ...notDeleting,
        'motionPreview.revision': state.revision,
        'motionPreview.pending.s3Key': pending.s3Key
    }, {
        'motionPreview.pending.status': 'failed',
        'motionPreview.pending.updatedAt': deps.now(),
        ...(target ? {
            'motionPreview.pending.versionId': target.versionId,
            'motionPreview.pending.outcomeUnknown': false
        } : {}),
        'motionPreview.revision': state.revision + 1
    });
    if (fenced.matchedCount !== 1) throw conflict('ADMIN_MOTION_PREVIEW_STALE_REVISION');
    if (target) {
        try {
            await deps.deleteObject(target.key, target.versionId);
            if (pending.outcomeUnknown && await deps.headObject(target.key)) {
                throw new Error('The pending preview object still exists after deletion.');
            }
        } catch {
            // The fenced record now names the exact version, so a retry deletes it without HEAD.
            throw reconciliationRequired();
        }
    }
    const cleared = await deps.updateTrackWhere(mediaTrackId, {
        ...notDeleting,
        'motionPreview.revision': state.revision + 1,
        'motionPreview.pending.s3Key': pending.s3Key
    }, { 'motionPreview.pending': null, 'motionPreview.revision': state.revision + 2 });
    if (cleared.matchedCount !== 1) throw conflict('ADMIN_MOTION_PREVIEW_STALE_REVISION');
};

/**
 * Detaches an active preview that is no longer bound to the track's active Video (or whose track is
 * no longer a ready Video) and deletes it. The preview is already hidden by the public gate, so a
 * failed delete only leaves a traceable cleanup record. Never throws.
 */
export const retireStaleMotionPreview = async (
    mediaTrackId: string,
    dependencyOverrides: Partial<MotionPreviewLifecycleDependencies> = {}
): Promise<{ retired: boolean; cleanupPending: boolean }> => {
    const deps = { ...defaultDependencies, ...dependencyOverrides };
    try {
        const track = await deps.findTrack(mediaTrackId);
        // Deletion owns every preview object once it begins, so retiring never races its fence.
        if (deletionOwns(track)) return { retired: false, cleanupPending: false };
        const state = stateOf(track);
        const active = state?.active;
        if (!state || !active || state.pending || state.cleanup) return { retired: false, cleanupPending: false };
        const source = previewSourceFor(track, mediaTrackId);
        if (source && active.source?.s3Key === source.sourceKey) return { retired: false, cleanupPending: false };
        const detached = await deps.updateTrackWhere(mediaTrackId, {
            ...notDeleting,
            'motionPreview.revision': state.revision,
            'motionPreview.active.s3Key': active.s3Key,
            'motionPreview.pending': null,
            'motionPreview.cleanup': null
        }, {
            'motionPreview.active': null,
            'motionPreview.cleanup': {
                status: 'pending', s3Key: active.s3Key, versionId: active.versionId ?? null,
                reason: 'stale', updatedAt: deps.now(), error: null
            },
            'motionPreview.revision': state.revision + 1
        });
        if (detached.matchedCount !== 1) return { retired: false, cleanupPending: false };
        return { retired: true, ...(await drainCleanup(mediaTrackId, deps)) };
    } catch {
        return { retired: false, cleanupPending: true };
    }
};

/** Administrator-safe summary of one track's preview; never exposes storage keys or versions. */
export const motionPreviewStatus = async (
    mediaTrackId: string,
    dependencyOverrides: Partial<MotionPreviewLifecycleDependencies> = {}
) => {
    const deps = { ...defaultDependencies, ...dependencyOverrides };
    const track = await deps.findTrack(mediaTrackId);
    if (!track) throw new MotionPreviewLifecycleError(404, 'ADMIN_MOTION_PREVIEW_NOT_FOUND');
    const source = previewSourceFor(track, mediaTrackId);
    const state = stateOf(track);
    const active = state?.active ?? null;
    return {
        eligible: Boolean(source) && !track.pendingS3Key,
        sourceToken: source ? motionPreviewSourceToken(mediaTrackId, source.sourceKey) : null,
        revision: state?.revision ?? 0,
        active: active ? {
            revision: active.revision,
            byteLength: active.byteLength,
            durationMs: active.durationMs,
            width: active.width,
            height: active.height,
            current: Boolean(source) && active.source?.s3Key === source?.sourceKey,
            updatedAt: active.updatedAt
        } : null,
        pending: state?.pending ? {
            status: state.pending.status,
            outcomeUnknown: state.pending.outcomeUnknown,
            leaseActive: new Date(state.pending.leaseUntil).getTime() > deps.now().getTime()
        } : null,
        cleanup: state?.cleanup ? { status: state.cleanup.status, reason: state.cleanup.reason } : null
    };
};

export interface MotionPreviewUploadRequest {
    actorId: string;
    mediaTrackId: string;
    file: Express.Multer.File;
    sourceToken: string;
    expectedRevision: number;
    signal?: AbortSignal;
}

/** Refuses a request that targets a missing or ineligible track, another Video, or an older revision. */
const checkUploadTarget = (track: any, request: MotionPreviewUploadRequest) => {
    if (!track) throw new MotionPreviewLifecycleError(404, 'ADMIN_MOTION_PREVIEW_NOT_FOUND');
    const source = previewSourceFor(track, request.mediaTrackId);
    if (!source) throw conflict('ADMIN_MOTION_PREVIEW_SOURCE_UNSUPPORTED');
    if (motionPreviewSourceToken(request.mediaTrackId, source.sourceKey) !== request.sourceToken) {
        throw conflict('ADMIN_MOTION_PREVIEW_SOURCE_CHANGED');
    }
    if (track.pendingS3Key) throw conflict('ADMIN_MOTION_PREVIEW_BUSY');
    // Status reports revision 0 before the record exists, which the freshly created record matches.
    if ((stateOf(track)?.revision ?? 0) !== request.expectedRevision) {
        throw conflict('ADMIN_MOTION_PREVIEW_STALE_REVISION');
    }
    return source;
};

/**
 * Validates, stores, and promotes a preview for the exact active Video it was made for. The old
 * preview stays public until promotion; failures at each step leave exact, recoverable evidence.
 */
export const uploadMotionPreview = async (
    request: MotionPreviewUploadRequest,
    dependencyOverrides: Partial<MotionPreviewLifecycleDependencies> = {}
) => {
    const deps = { ...defaultDependencies, ...dependencyOverrides };
    const { actorId, mediaTrackId, file, signal } = request;
    // Cheap refusals come first, so a stale or ineligible request never holds the one decoder slot.
    checkUploadTarget(await deps.findTrack(mediaTrackId), request);
    const validated = await deps.validate(file, signal);

    // The track can change during the decode, so the request is checked again before any write.
    const initial = await deps.findTrack(mediaTrackId);
    const source = checkUploadTarget(initial, request);
    const ensured = await ensureState(mediaTrackId, deps);
    if (stateOf(ensured)!.revision !== request.expectedRevision) throw conflict('ADMIN_MOTION_PREVIEW_STALE_REVISION');

    await drainPending(mediaTrackId, deps);
    await retireStaleMotionPreview(mediaTrackId, deps);
    if ((await drainCleanup(mediaTrackId, deps)).cleanupPending) throw conflict('ADMIN_MOTION_PREVIEW_CLEANUP_PENDING');

    const ready = await deps.findTrack(mediaTrackId);
    const readyState = stateOf(ready);
    if (!readyState || readyState.pending || readyState.cleanup) throw conflict('ADMIN_MOTION_PREVIEW_BUSY');
    const sourceBinding = {
        uploadStatus: 'ready',
        mediaType: 'video',
        s3Key: source.sourceKey,
        pendingS3Key: null
    };

    const key = deps.createObjectKey(mediaTrackId);
    if (!isMotionPreviewObjectKeyForTrack(key, mediaTrackId)) throw new Error('Motion preview key is invalid.');
    let revision = readyState.revision;
    const reserved = await deps.updateTrackWhere(mediaTrackId, {
        ...sourceBinding,
        'motionPreview.revision': revision,
        'motionPreview.pending': null,
        'motionPreview.cleanup': null
    }, {
        'motionPreview.pending': {
            status: 'uploading', s3Key: key, versionId: null, outcomeUnknown: true,
            source: { s3Key: source.sourceKey },
            leaseUntil: new Date(deps.now().getTime() + MOTION_PREVIEW_LEASE_MS),
            updatedAt: deps.now(), error: null
        },
        'motionPreview.revision': revision + 1
    });
    if (reserved.matchedCount !== 1) throw conflict('ADMIN_MOTION_PREVIEW_STALE_REVISION');
    revision += 1;

    let stored: { ETag?: string; VersionId?: string };
    try {
        stored = await deps.putObject(key, file, {
            trackid: mediaTrackId,
            // Storage metadata names the MediaTrack's shared provenance, as Video uploads do.
            ownerid: String(ready.createdBy ?? '') || actorId,
            sha256: validated.sha256
        }, signal);
    } catch (error) {
        const status = statusOf(error);
        const definite = status >= 400 && status < 500 && status !== 408 && status !== 412;
        await deps.updateTrackWhere(mediaTrackId, {
            ...notDeleting,
            'motionPreview.revision': revision,
            'motionPreview.pending.s3Key': key
        }, definite
            ? { 'motionPreview.pending': null, 'motionPreview.revision': revision + 1 }
            : {
                'motionPreview.pending.status': 'failed',
                'motionPreview.pending.updatedAt': deps.now(),
                'motionPreview.pending.error': errorText(error),
                'motionPreview.revision': revision + 1
            }).catch(() => undefined);
        throw definite
            ? new MotionPreviewLifecycleError(502, 'ADMIN_MOTION_PREVIEW_STORAGE_FAILED')
            : new MotionPreviewLifecycleError(503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    }

    const versionId = stored.VersionId ?? null;
    /**
     * Removes this upload's own exact object after a failed step. The pending record is fenced
     * first, so a late write from this upload (such as a promote whose acknowledgement was lost)
     * can no longer land. Returns false when the fence misses. After a promote attempt the object
     * may then be live, so it is kept for an explicit recovery; before one it can never be active
     * (only this upload promotes its never-reused key), so it is still deleted by exact version and
     * any record that names it only meets an idempotent second delete.
     */
    const abandonUpload = async (fromRevision: number, { beforePromote = false } = {}) => {
        const fence = {
            ...notDeleting,
            'motionPreview.pending.s3Key': key
        };
        const fenced = await deps.updateTrackWhere(mediaTrackId, {
            ...fence,
            'motionPreview.revision': fromRevision
        }, {
            'motionPreview.pending.status': 'failed',
            'motionPreview.pending.versionId': versionId,
            'motionPreview.pending.outcomeUnknown': false,
            'motionPreview.pending.updatedAt': deps.now(),
            'motionPreview.revision': fromRevision + 1
        }).catch(() => ({ matchedCount: 0 }));
        if (fenced.matchedCount !== 1) {
            if (beforePromote) await deps.deleteObject(key, versionId).catch(() => undefined);
            return false;
        }
        try {
            await deps.deleteObject(key, versionId);
        } catch (error) {
            await deps.updateTrackWhere(mediaTrackId, {
                ...fence,
                'motionPreview.revision': fromRevision + 1
            }, {
                'motionPreview.pending.error': errorText(error),
                'motionPreview.revision': fromRevision + 2
            }).catch(() => undefined);
            return true;
        }
        await deps.updateTrackWhere(mediaTrackId, {
            ...fence,
            'motionPreview.revision': fromRevision + 1
        }, { 'motionPreview.pending': null, 'motionPreview.revision': fromRevision + 2 }).catch(() => undefined);
        return true;
    };

    const recorded = await deps.updateTrackWhere(mediaTrackId, {
        ...notDeleting,
        'motionPreview.revision': revision,
        'motionPreview.pending.s3Key': key
    }, {
        'motionPreview.pending.versionId': versionId,
        'motionPreview.pending.outcomeUnknown': false,
        'motionPreview.revision': revision + 1
    }).catch(() => ({ matchedCount: 0 }));
    if (recorded.matchedCount !== 1) {
        await abandonUpload(revision, { beforePromote: true });
        throw new MotionPreviewLifecycleError(503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
    }
    revision += 1;

    if (typeof stored.ETag !== 'string' || !/^"[^"\r\n]{1,200}"$/.test(stored.ETag)) {
        await abandonUpload(revision, { beforePromote: true });
        throw new MotionPreviewLifecycleError(502, 'ADMIN_MOTION_PREVIEW_STORAGE_FAILED');
    }

    const current = stateOf(await deps.findTrack(mediaTrackId));
    const previous = current?.active ?? null;
    const active: MotionPreviewActive = {
        status: 'ready',
        revision: deps.randomRevision(),
        s3Key: key,
        versionId,
        etag: stored.ETag,
        byteLength: validated.byteLength,
        contentType: 'video/mp4',
        durationMs: validated.durationMs,
        width: validated.width,
        height: validated.height,
        sha256: validated.sha256,
        source: { s3Key: source.sourceKey },
        updatedBy: actorId,
        updatedAt: deps.now()
    };
    const promoted = await deps.updateTrackWhere(mediaTrackId, {
        ...sourceBinding,
        'motionPreview.revision': revision,
        'motionPreview.pending.s3Key': key,
        'motionPreview.cleanup': null
    }, {
        'motionPreview.active': active,
        'motionPreview.pending': null,
        'motionPreview.cleanup': previous ? {
            status: 'pending', s3Key: previous.s3Key, versionId: previous.versionId ?? null,
            reason: 'replaced', updatedAt: deps.now(), error: null
        } : null,
        'motionPreview.revision': revision + 1
    }).catch(() => ({ matchedCount: 0 }));
    if (promoted.matchedCount !== 1) {
        // A fence that lands proves the promote did not; one that misses means it may have.
        if (await abandonUpload(revision)) throw conflict('ADMIN_MOTION_PREVIEW_SOURCE_CHANGED');
        const confirmed = stateOf(await deps.findTrack(mediaTrackId).catch(() => null));
        if (confirmed?.active?.s3Key !== key) {
            throw new MotionPreviewLifecycleError(503, 'ADMIN_MOTION_PREVIEW_RECONCILIATION_REQUIRED');
        }
    }

    // The preview is committed; a failed cleanup read is reported as pending, never as a failure.
    const { cleanupPending } = await drainCleanup(mediaTrackId, deps).catch(() => ({ cleanupPending: true }));
    return {
        revision: active.revision,
        durationMs: active.durationMs,
        width: active.width,
        height: active.height,
        byteLength: active.byteLength,
        cleanupPending
    };
};

/** Removes the active preview on request; a Video without a preview remains valid. */
export const removeMotionPreview = async (
    mediaTrackId: string,
    expectedRevision: number,
    dependencyOverrides: Partial<MotionPreviewLifecycleDependencies> = {}
) => {
    const deps = { ...defaultDependencies, ...dependencyOverrides };
    const track = await deps.findTrack(mediaTrackId);
    if (!track) throw new MotionPreviewLifecycleError(404, 'ADMIN_MOTION_PREVIEW_NOT_FOUND');
    const state = stateOf(track);
    if (!state?.active) throw new MotionPreviewLifecycleError(404, 'ADMIN_MOTION_PREVIEW_NOT_FOUND');
    if (state.revision !== expectedRevision) throw conflict('ADMIN_MOTION_PREVIEW_STALE_REVISION');
    if (state.pending || state.cleanup || deletionOwns(track)) throw conflict('ADMIN_MOTION_PREVIEW_BUSY');
    const detached = await deps.updateTrackWhere(mediaTrackId, {
        ...notDeleting,
        'motionPreview.revision': state.revision,
        'motionPreview.active.s3Key': state.active.s3Key,
        'motionPreview.pending': null,
        'motionPreview.cleanup': null
    }, {
        'motionPreview.active': null,
        'motionPreview.cleanup': {
            status: 'pending', s3Key: state.active.s3Key, versionId: state.active.versionId ?? null,
            reason: 'removed', updatedAt: deps.now(), error: null
        },
        'motionPreview.revision': state.revision + 1
    });
    if (detached.matchedCount !== 1) throw conflict('ADMIN_MOTION_PREVIEW_STALE_REVISION');
    // The removal is committed; a failed cleanup read is reported as pending, never as a failure.
    return drainCleanup(mediaTrackId, deps).catch(() => ({ cleanupPending: true }));
};

/** Explicit administrator recovery of an expired pending upload and a retained cleanup object. */
export const reconcileMotionPreview = async (
    mediaTrackId: string,
    dependencyOverrides: Partial<MotionPreviewLifecycleDependencies> = {}
) => {
    const deps = { ...defaultDependencies, ...dependencyOverrides };
    await ensureState(mediaTrackId, deps);
    await drainPending(mediaTrackId, deps);
    await retireStaleMotionPreview(mediaTrackId, deps);
    return drainCleanup(mediaTrackId, deps);
};
